import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, useNavigate } from 'react-router-dom';
import ReviewList from './ReviewList';
import UpdateReview from './UpdateReview';

interface Review {
  _id: string;
  customerName: string;
  reviewText: string;
  rating: number;
}

// This is a wrapper component to handle navigation
const ReviewsPage: React.FC = () => {
  const [reviews, setReviews] = useState<Review[]>([]);
  const navigate = useNavigate();

  useEffect(() => {
    // Fetch reviews from your API
    fetchReviews();
  }, []);

  const fetchReviews = async () => {
    try {
      // Replace with your actual API endpoint
      const response = await fetch('/api/reviews');
      const data = await response.json();
      setReviews(data);
    } catch (error) {
      console.error('Error fetching reviews:', error);
    }
  };

  const handleEdit = (review: Review) => {
    // This will navigate to the update page with the review ID
    navigate(`/reviews/${review._id}/edit`);
  };

  const handleDelete = async (reviewId: string) => {
    try {
      // Replace with your actual API endpoint
      await fetch(`/api/reviews/${reviewId}`, {
        method: 'DELETE',
      });
      // Refresh reviews after deletion
      fetchReviews();
    } catch (error) {
      console.error('Error deleting review:', error);
    }
  };

  return (
    <ReviewList
      reviews={reviews}
      onEdit={handleEdit}
      onDelete={handleDelete}
    />
  );
};

// Main App component with routing
const App: React.FC = () => {
  return (
    <Router>
      <Routes>
        <Route path="/reviews" element={<ReviewsPage />} />
        <Route path="/reviews/:id/edit" element={<UpdateReview />} />
        {/* Add other routes as needed */}
        <Route path="/" element={<ReviewsPage />} />
      </Routes>
    </Router>
  );
};

export default App;