import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import './Update.css';

interface Review {
  _id: string;
  customerName: string;
  reviewText: string;
  rating: number;
}

const Update: React.FC = () => {
  const [review, setReview] = useState<Review | null>(null);
  const [customerName, setCustomerName] = useState('');
  const [reviewText, setReviewText] = useState('');
  const [rating, setRating] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  // Fetch the review data on component mount
  useEffect(() => {
    const fetchReview = async () => {
      try {
        setIsLoading(true);
        // Replace with your actual API endpoint
        const response = await fetch(`/api/reviews/${id}`);
        if (!response.ok) {
          throw new Error('Failed to fetch review');
        }
        const data = await response.json();
        setReview(data);
        setCustomerName(data.customerName);
        setReviewText(data.reviewText);
        setRating(data.rating);
      } catch (err) {
        setError('Failed to load review. Please try again later.');
        console.error('Error fetching review:', err);
      } finally {
        setIsLoading(false);
      }
    };

    if (id) {
      fetchReview();
    }
  }, [id]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    try {
      setIsLoading(true);
      // Replace with your actual API endpoint
      const response = await fetch(`/api/reviews/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          customerName,
          reviewText,
          rating,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to update review');
      }

      // Navigate back to reviews page after successful update
      navigate('/reviews');
    } catch (err) {
      setError('Failed to update review. Please try again.');
      console.error('Error updating review:', err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRatingChange = (selectedRating: number) => {
    setRating(selectedRating);
  };

  // Show loading state
  if (isLoading && !review) {
    return <div className="loading">Loading review...</div>;
  }

  // Show error state
  if (error && !review) {
    return <div className="error">{error}</div>;
  }

  return (
    <div className="update-review-container">
      <h2>Update Your Review</h2>
      <form onSubmit={handleSubmit} className="review-form">
        <div className="form-group">
          <label htmlFor="customerName">Your Name</label>
          <input
            type="text"
            id="customerName"
            value={customerName}
            onChange={(e) => setCustomerName(e.target.value)}
            required
          />
        </div>

        <div className="form-group">
          <label>Rating</label>
          <div className="rating-selector">
            {[1, 2, 3, 4, 5].map((star) => (
              <span
                key={star}
                className={`star-input ${star <= rating ? 'selected' : ''}`}
                onClick={() => handleRatingChange(star)}
              >
                ★
              </span>
            ))}
          </div>
        </div>

        <div className="form-group">
          <label htmlFor="reviewText">Review</label>
          <textarea
            id="reviewText"
            value={reviewText}
            onChange={(e) => setReviewText(e.target.value)}
            rows={5}
            required
          />
        </div>

        {error && <div className="error-message">{error}</div>}

        <div className="form-actions">
          <button 
            type="button" 
            className="cancel-button" 
            onClick={() => navigate('/reviews')}
          >
            Cancel
          </button>
          <button 
            type="submit" 
            className="submit-button"
            disabled={isLoading}
          >
            {isLoading ? 'Updating...' : 'Update Review'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default Update;